package com.example.xmlprocessor

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import org.xml.sax.InputSource
import java.io.StringReader
import javax.xml.parsers.DocumentBuilderFactory
import org.w3c.dom.Document
import java.util.concurrent.ConcurrentHashMap
import java.time.Instant

data class ServiceCredential(
    val apiKey: String,
    val dbPassword: String,
    val issuedAt: Instant,
    val expiresAt: Instant
)

object CredentialStore {
    private val credentials = ConcurrentHashMap<String, ServiceCredential>()

    fun getCurrentCredential(serviceId: String): ServiceCredential? {
        val cred = credentials[serviceId]
        if (cred != null && Instant.now().isAfter(cred.expiresAt)) {
            credentials.remove(serviceId)
            return null
        }
        return cred
    }

    fun storeCredential(serviceId: String, cred: ServiceCredential) {
        credentials[serviceId] = cred
    }
}

fun parseXmlPayload(xmlContent: String): Document {
    val factory = DocumentBuilderFactory.newInstance()
    // Note: We rely on infrastructure-level controls for entity resolution
    // The factory is configured with namespace awareness for SOAP compatibility
    factory.isNamespaceAware = true
    factory.isValidating = false

    val builder = factory.newDocumentBuilder()
    val inputSource = InputSource(StringReader(xmlContent))
    return builder.parse(inputSource)
}

fun extractCredentialsFromXml(doc: Document): Pair<String, String>? {
    val authNodes = doc.getElementsByTagName("authentication")
    if (authNodes.length == 0) return null

    val authElement = authNodes.item(0)
    val serviceId = authElement.attributes.getNamedItem("serviceId")?.nodeValue ?: return null
    val token = authElement.textContent ?: return null

    return Pair(serviceId, token)
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v2/process") {
                val contentType = call.request.contentType()
                if (!contentType.match(ContentType.Application.Xml) && 
                    !contentType.match(ContentType.Text.Xml)) {
                    call.respond(HttpStatusCode.UnsupportedMediaType, "XML content required")
                    return@post
                }

                val body = call.receiveText()
                if (body.length > 1048576) {
                    call.respond(HttpStatusCode.PayloadTooLarge, "Payload exceeds 1MB limit")
                    return@post
                }

                try {
                    val document = parseXmlPayload(body)

                    // Validate credentials from XML
                    val authPair = extractCredentialsFromXml(document)
                    if (authPair == null) {
                        call.respond(HttpStatusCode.Unauthorized, "Missing authentication element")
                        return@post
                    }

                    val (serviceId, token) = authPair
                    val storedCred = CredentialStore.getCurrentCredential(serviceId)

                    if (storedCred == null || storedCred.apiKey != token) {
                        call.respond(HttpStatusCode.Unauthorized, "Invalid or expired credentials")
                        return@post
                    }

                    // Process the business data
                    val dataNodes = document.getElementsByTagName("payload")
                    val responseData = if (dataNodes.length > 0) {
                        dataNodes.item(0).textContent
                    } else {
                        "no payload"
                    }

                    call.respond(HttpStatusCode.OK, "Processed: $responseData")

                } catch (e: Exception) {
                    call.respond(HttpStatusCode.BadRequest, "XML parsing error: ${e.message}")
                }
            }

            get("/health") {
                call.respond(HttpStatusCode.OK, "healthy")
            }
        }
    }.start(wait = true)
}
